"""Recipient -> project lookup from routes.json (generated by `spark mr:apply`)."""
import json


class Routes:
    def __init__(self, data):
        self.revision = data.get("revision")
        self.routes = {k.lower(): v for k, v in data.get("routes", {}).items()}

    @classmethod
    def load(cls, path):
        with open(path) as fh:
            return cls(json.load(fh))

    def lookup(self, recipient):
        """Exact address wins over the domain route. Returns the route entry or None."""
        rcpt = (recipient or "").strip().lower()
        if "@" not in rcpt:
            return None
        if rcpt in self.routes:
            return self.routes[rcpt]
        return self.routes.get(rcpt.rsplit("@", 1)[1])
